const AliCloudConfigureRequestSchema = z
  .object({
    access_key: z
      .string()
      .exactOptional()
      .openapi({ description: 'Access key with appropriate permissions.' }),
    secret_key: z
      .string()
      .exactOptional()
      .openapi({ description: 'Secret key with appropriate permissions.' }),
  })
  .openapi({ required: [] })
  .openapi('AliCloudConfigureRequest')

const AliCloudLoginRequestSchema = z
  .object({
    identity_request_headers: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'The request headers. This must include the headers over which AliCloud has included a signature.',
      }),
    identity_request_url: z
      .string()
      .exactOptional()
      .openapi({
        description: 'Base64-encoded full URL against which to make the AliCloud request.',
      }),
    role: z
      .string()
      .openapi({
        description:
          "Name of the role against which the login is being attempted. If 'role' is not specified, then the login endpoint looks for a role name in the ARN returned by the GetCallerIdentity request. If a matching role is not found, login fails.",
      }),
  })
  .openapi({ required: ['role'] })
  .openapi('AliCloudLoginRequest')

const AliCloudWriteAuthRoleRequestSchema = z
  .object({
    arn: z
      .string()
      .exactOptional()
      .openapi({ description: 'ARN of the RAM to bind to this role.' }),
    bound_cidrs: z
      .array(z.string())
      .exactOptional()
      .openapi({
        description:
          'Use "token_bound_cidrs" instead. If this and "token_bound_cidrs" are both specified, only "token_bound_cidrs" will be used.',
        deprecated: true,
      }),
    max_ttl: z.iso
      .duration()
      .exactOptional()
      .openapi({
        description:
          'Use "token_max_ttl" instead. If this and "token_max_ttl" are both specified, only "token_max_ttl" will be used.',
        deprecated: true,
      }),
    period: z.iso
      .duration()
      .exactOptional()
      .openapi({
        description:
          'Use "token_period" instead. If this and "token_period" are both specified, only "token_period" will be used.',
        deprecated: true,
      }),
    policies: z
      .array(z.string())
      .exactOptional()
      .openapi({
        description:
          'Use "token_policies" instead. If this and "token_policies" are both specified, only "token_policies" will be used.',
        deprecated: true,
      }),
    token_bound_cidrs: z
      .array(z.string())
      .exactOptional()
      .openapi({
        description:
          'Comma separated string or JSON list of CIDR blocks. If set, specifies the blocks of IP addresses which are allowed to use the generated token.',
        'x-vault-displayAttrs': {
          name: "Generated Token's Bound CIDRs",
          description:
            'A list of CIDR blocks. If set, specifies the blocks of IP addresses which are allowed to use the generated token.',
          group: 'Tokens',
        },
      }),
    token_explicit_max_ttl: z.iso
      .duration()
      .exactOptional()
      .openapi({
        description:
          'If set, tokens created via this role carry an explicit maximum TTL. During renewal, the current maximum TTL values of the role and the mount are not checked for changes, and any updates to these values will have no effect on the token being renewed.',
        'x-vault-displayAttrs': { name: "Generated Token's Explicit Maximum TTL", group: 'Tokens' },
      }),
    token_max_ttl: z.iso
      .duration()
      .exactOptional()
      .openapi({
        description: 'The maximum lifetime of the generated token',
        'x-vault-displayAttrs': { name: "Generated Token's Maximum TTL", group: 'Tokens' },
      }),
    token_no_default_policy: z
      .boolean()
      .exactOptional()
      .openapi({
        description:
          "If true, the 'default' policy will not automatically be added to generated tokens",
        'x-vault-displayAttrs': {
          name: "Do Not Attach 'default' Policy To Generated Tokens",
          group: 'Tokens',
        },
      }),
    token_num_uses: z
      .int()
      .exactOptional()
      .openapi({
        description:
          'The maximum number of times a token may be used, a value of zero means unlimited',
        'x-vault-displayAttrs': { name: 'Maximum Uses of Generated Tokens', group: 'Tokens' },
      }),
    token_period: z.iso
      .duration()
      .exactOptional()
      .openapi({
        description:
          'If set, tokens created via this role will have no max lifetime; instead, their renewal period will be fixed to this value. This takes an integer number of seconds, or a string duration (e.g. "24h").',
        'x-vault-displayAttrs': { name: "Generated Token's Period", group: 'Tokens' },
      }),
    token_policies: z
      .array(z.string())
      .exactOptional()
      .openapi({
        description: 'Comma-separated list of policies',
        'x-vault-displayAttrs': {
          name: "Generated Token's Policies",
          description: 'A list of policies that will apply to the generated token for this user.',
          group: 'Tokens',
        },
      }),
    token_ttl: z.iso
      .duration()
      .exactOptional()
      .openapi({
        description: 'The initial ttl of the token to generate',
        'x-vault-displayAttrs': { name: "Generated Token's Initial TTL", group: 'Tokens' },
      }),
    token_type: z
      .string()
      .default('default-service')
      .exactOptional()
      .openapi({
        description: 'The type of token to generate, service or batch',
        'x-vault-displayAttrs': { name: "Generated Token's Type", group: 'Tokens' },
      }),
    ttl: z.iso
      .duration()
      .exactOptional()
      .openapi({
        description:
          'Use "token_ttl" instead. If this and "token_ttl" are both specified, only "token_ttl" will be used.',
        deprecated: true,
      }),
  })
  .openapi({ required: [] })
  .openapi('AliCloudWriteAuthRoleRequest')

const AliCloudWriteRoleRequestSchema = z
