export const getIdentityOidcProviderNameAuthorizeRoute = createRoute({
  method: 'get',
  path: '/identity/oidc/provider/{name}/authorize',
  tags: ['identity'],
  operationId: 'oidc-provider-authorize',
  request: {
    params: z.object({
      name: z
        .string()
        .openapi({
          param: {
            name: 'name',
            description: 'Name of the provider',
            in: 'path',
            schema: { type: 'string' },
            required: true,
          },
        }),
    }),
    query: z.object({
      client_id: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'client_id',
            description: 'The ID of the requesting client.',
            in: 'query',
            schema: { type: 'string' },
            required: false,
          },
        }),
      code_challenge: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'code_challenge',
            description: 'The code challenge derived from the code verifier.',
            in: 'query',
            schema: { type: 'string' },
            required: false,
          },
        }),
      code_challenge_method: z
        .string()
        .default('plain')
        .exactOptional()
        .openapi({
          param: {
            name: 'code_challenge_method',
            description:
              "The method that was used to derive the code challenge. The following methods are supported: 'S256', 'plain'. Defaults to 'plain'.",
            in: 'query',
            schema: { type: 'string', default: 'plain' },
            required: false,
          },
        }),
      max_age: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'max_age',
            description:
              'The allowable elapsed time in seconds since the last time the end-user was actively authenticated.',
            in: 'query',
            schema: { type: 'integer' },
            required: false,
          },
        }),
      nonce: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'nonce',
            description:
              'The value that will be returned in the ID token nonce claim after a token exchange.',
            in: 'query',
            schema: { type: 'string' },
            required: false,
          },
        }),
      redirect_uri: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'redirect_uri',
            description: 'The redirection URI to which the response will be sent.',
            in: 'query',
            schema: { type: 'string' },
            required: false,
          },
        }),
      response_type: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'response_type',
            description:
              "The OIDC authentication flow to be used. The following response types are supported: 'code'",
            in: 'query',
            schema: { type: 'string' },
            required: false,
          },
        }),
      scope: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'scope',
            description:
              "A space-delimited, case-sensitive list of scopes to be requested. The 'openid' scope is required.",
            in: 'query',
            schema: { type: 'string' },
            required: false,
          },
        }),
      state: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'state',
            description:
              'The value used to maintain state between the authentication request and client.',
            in: 'query',
            schema: { type: 'string' },
            required: false,
          },
        }),
    }),
  },
  responses: { 200: { description: 'OK' } },
})

