export const getSysMonitorRoute = createRoute({
  method: 'get',
  path: '/sys/monitor',
  tags: ['system'],
  operationId: 'monitor',
  request: {
    query: z.object({
      log_format: z
        .string()
        .default('standard')
        .exactOptional()
        .openapi({
          param: {
            name: 'log_format',
            description:
              'Output format of logs. Supported values are "standard" and "json". The default is "standard".',
            in: 'query',
            schema: { type: 'string', default: 'standard' },
            required: false,
          },
        }),
      log_level: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'log_level',
            description:
              'Log level to view system logs at. Currently supported values are "trace", "debug", "info", "warn", "error".',
            in: 'query',
            schema: { type: 'string' },
            required: false,
          },
        }),
    }),
  },
  responses: { 200: { description: 'OK' } },
})

